-- ============================================================
--  PREVISION CLORO  ·  normalizar las facturas de contado del historico
--
--  Las temporadas 2024-2025 y 2025-2026 entraron por cloro_seed.sql,
--  generado ANTES de que existiera la regla de contado. La 2026-2027 se
--  importa de nuevo desde la pantalla, que ya la aplica sola.
--
--  LA REGLA: los documentos "Contado *DDMMAA..." se emiten en lote al
--  cierre del mes, asi que su fecha es la de EMISION y no la de la
--  venta. Su cantidad se reparte pareja del 1 al 15 del mes de la
--  factura y la fila original no se carga.
--
--  Son 417 facturas y 11.598 unidades, el 8,8% del historico.
--
--  EL TOTAL POR PRODUCTO NO CAMBIA: se verificaron las 26 combinaciones
--  producto-temporada contra los .xls, una por una, antes de generar
--  esto. Lo que cambia es en que SEMANA cae cada unidad: el pico de
--  2025-26 pasa de 15.004 a 13.028 en la semana 23.
--
--  Se borran las semanas de esas dos temporadas y se insertan de nuevo.
--  No se toca 2026-2027 ni ninguna otra tabla.
-- ============================================================

delete from public.cl_ventas
 where temporada_id in (select id from public.cl_temporadas
                         where nombre in ('2024-2025','2025-2026'));

insert into public.cl_ventas (temporada_id, producto_id, semana, unidades, origen)
