  join public.cl_productos  p on p.codigo = v.codigo;

-- Control: tienen que dar EXACTAMENTE estos totales, los mismos de antes
-- de normalizar.
--   2024-2025 = 61645 unidades
--   2025-2026 = 69454 unidades
select t.nombre, count(*) as semanas, round(sum(v.unidades)) as unidades
  from public.cl_ventas v join public.cl_temporadas t on t.id = v.temporada_id
 group by t.nombre order by t.nombre;
